import { getServerConfig } from './credentialsManager.js';

export interface AdGuardConfig {
  url: string;
  username?: string;
  password?: string;
}

let currentConfig: AdGuardConfig = {
  url: 'http://127.0.0.1:8081',
  username: 'samuel',
  password: 'REDACTED_PASSWORD'
};

// Telemetria AdGuard Home: inicializada como nula para garantir ZERO dados fake
let lastCapturedStats: any = null;
let lastCapturedQueryLog: any[] = [];

export function getAdGuardConfig(): AdGuardConfig {
  const fileConfig = getServerConfig().adguard;
  return {
    url: fileConfig?.url || currentConfig.url,
    username: fileConfig?.username || currentConfig.username,
  };
}

export function updateAdGuardConfig(cfg: Partial<AdGuardConfig>): AdGuardConfig {
  if (cfg.url) currentConfig.url = cfg.url.trim().replace(/\/$/, '');
  if (cfg.username !== undefined) currentConfig.username = cfg.username.trim();
  if (cfg.password !== undefined && cfg.password !== '') currentConfig.password = cfg.password.trim();
  return getAdGuardConfig();
}

export function getActiveAdGuardCredentials() {
  const fileConfig = getServerConfig().adguard;
  const url = (fileConfig?.url || currentConfig.url || 'http://127.0.0.1:8081').replace(/\/$/, '');
  const username = fileConfig?.username || currentConfig.username || 'samuel';
  const password = fileConfig?.password !== undefined && fileConfig.password !== '' 
    ? fileConfig.password 
    : (currentConfig.password || 'REDACTED_PASSWORD');
  return { url, username, password };
}

export function getAdGuardClearCommand(): string {
  const { url, username, password } = getActiveAdGuardCredentials();
  return `curl -s -X POST -u "${username}:${password}" ${url}/control/querylog_clear && curl -s -X POST -u "${username}:${password}" ${url}/control/stats_reset`;
}

async function makeAdGuardRequest(endpoint: string, method: 'GET' | 'POST' = 'GET', body?: any): Promise<{ ok: boolean; status: number; data: any; error?: string }> {
  const { url, username, password } = getActiveAdGuardCredentials();

  // Candidatos de base URL agnósticos a IP: loopback IPv4 e IPv6
  const basesToTry = [
    'http://127.0.0.1:8081',
    'http://[::1]:8081',
    'http://localhost:8081',
    url.replace(/\/$/, '')
  ];
  const uniqueBases = Array.from(new Set(basesToTry));

  const baseHeaders: Record<string, string> = {
    'Accept': 'application/json',
    'User-Agent': 'AdGuard-Panel/1.0'
  };

  if (body) {
    baseHeaders['Content-Type'] = 'application/json';
  }

  const basicAuthHeader = (username && password)
    ? `Basic ${Buffer.from(`${username}:${password}`).toString('base64')}`
    : undefined;

  for (const base of uniqueBases) {
    const targetUrl = `${base}${endpoint}`;
    
    // 1. Tenta sem Authorization (rede local / loopback Nginx)
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 2000);
      const res = await fetch(targetUrl, {
        method,
        headers: baseHeaders,
        body: body ? JSON.stringify(body) : undefined,
        signal: controller.signal
      });
      clearTimeout(timeoutId);

      if (res.ok) {
        let data = null;
        try {
          data = await res.json();
        } catch {
          data = { success: true };
        }
        return { ok: true, status: res.status, data };
      }

      // Se der 401 Unauthorized e temos credenciais, tenta com Basic Auth
      if (res.status === 401 && basicAuthHeader) {
        const authCtrl = new AbortController();
        const authTimer = setTimeout(() => authCtrl.abort(), 2000);
        const authRes = await fetch(targetUrl, {
          method,
          headers: { ...baseHeaders, 'Authorization': basicAuthHeader },
          body: body ? JSON.stringify(body) : undefined,
          signal: authCtrl.signal
        });
        clearTimeout(authTimer);

        if (authRes.ok) {
          let data = null;
          try {
            data = await authRes.json();
          } catch {
            data = { success: true };
          }
          return { ok: true, status: authRes.status, data };
        }
      }
    } catch {
      // Tenta próximo base
    }
  }

  return { ok: false, status: 0, data: null, error: 'Servidor AdGuard Home não respondeu em tempo hábil' };
}

export async function clearAdGuardHistory(): Promise<{ success: boolean; message: string; shellCommand: string }> {
  const shellCommand = getAdGuardClearCommand();

  try {
    await makeAdGuardRequest('/control/querylog_clear', 'POST');
    await makeAdGuardRequest('/control/stats_reset', 'POST');
  } catch (err: any) {
    console.warn('[adguardClient] Aviso ao limpar histórico via API interna:', err.message);
  }

  // Zera estatísticas capturadas para refletir limpeza real
  lastCapturedStats = {
    connected: true,
    isCached: false,
    num_dns_queries: 0,
    num_blocked_filtering: 0,
    num_replaced_safebrowsing: 0,
    num_replaced_safesearch: 0,
    blocked_percentage: 0,
    avg_processing_time: 0,
    top_queried_domains: [],
    top_blocked_domains: [],
    top_clients: [],
    top_upstreams_responses: [],
    dns_queries: [],
    blocked_filtering: [],
    time_units: 'hours',
    last_updated: new Date().toISOString()
  };
  lastCapturedQueryLog = [];

  return {
    success: true,
    message: 'Histórico de consultas e estatísticas do AdGuard zerados com sucesso.',
    shellCommand
  };
}

export async function fetchAdGuardStatus() {
  const result = await makeAdGuardRequest('/control/status');
  if (result.ok && result.data) {
    return {
      connected: true,
      online: true,
      running: result.data.running ?? true,
      protection_enabled: result.data.protection_enabled ?? true,
      version: result.data.version || 'v0.107.x',
      language: result.data.language || 'pt-br',
      url: currentConfig.url
    };
  }

  return {
    connected: false,
    online: false,
    running: false,
    protection_enabled: false,
    version: 'Desconectado',
    language: 'pt-br',
    url: currentConfig.url,
    error: 'AdGuard Home offline ou inacessível em :8081'
  };
}

export function updateAdGuardRawStats(d: any) {
  if (!d) return lastCapturedStats;
  const numDns = Number(d.num_dns_queries || 0);
  const numBlocked = Number(d.num_blocked_filtering || 0);
  const blockPct = numDns > 0 ? Number(((numBlocked / numDns) * 100).toFixed(1)) : 0;

  lastCapturedStats = {
    connected: true,
    online: true,
    stale: false,
    isCached: false,
    num_dns_queries: numDns,
    num_blocked_filtering: numBlocked,
    num_replaced_safebrowsing: Number(d.num_replaced_safebrowsing || 0),
    num_replaced_safesearch: Number(d.num_replaced_safesearch || 0),
    blocked_percentage: blockPct,
    avg_processing_time: Number(d.avg_processing_time || 0),
    top_queried_domains: Array.isArray(d.top_queried_domains) ? d.top_queried_domains : [],
    top_blocked_domains: Array.isArray(d.top_blocked_domains) ? d.top_blocked_domains : [],
    top_clients: Array.isArray(d.top_clients) ? d.top_clients : [],
    top_upstreams_responses: Array.isArray(d.top_upstreams_responses) ? d.top_upstreams_responses : [],
    dns_queries: Array.isArray(d.dns_queries) ? d.dns_queries : [],
    blocked_filtering: Array.isArray(d.blocked_filtering) ? d.blocked_filtering : [],
    time_units: d.time_units || 'hours',
    last_updated: new Date().toISOString()
  };
  return lastCapturedStats;
}

export async function fetchAdGuardStats() {
  const result = await makeAdGuardRequest('/control/stats');
  if (result.ok && result.data) {
    return updateAdGuardRawStats(result.data);
  }

  // Se falhou mas temos dados anteriores, sinaliza que o dado é ANTIGO (stale)
  if (lastCapturedStats) {
    return {
      ...lastCapturedStats,
      connected: false,
      online: false,
      stale: true,
      error: result.error || 'AdGuard Home offline ou inacessível no momento'
    };
  }

  // ZERO DADOS FAKES: Estado desconectado honesto
  return {
    connected: false,
    online: false,
    stale: true,
    isCached: false,
    num_dns_queries: 0,
    num_blocked_filtering: 0,
    blocked_percentage: 0,
    avg_processing_time: 0,
    top_queried_domains: [],
    top_blocked_domains: [],
    top_clients: [],
    top_upstreams_responses: [],
    dns_queries: [],
    blocked_filtering: [],
    time_units: 'hours',
    last_updated: '--:--:--',
    error: result.error || 'AdGuard Home offline ou inacessível em :8081'
  };
}

export async function fetchAdGuardQueryLog(limit: number = 30) {
  const result = await makeAdGuardRequest(`/control/querylog?limit=${limit}`);
  if (result.ok && result.data && Array.isArray(result.data.data)) {
    lastCapturedQueryLog = result.data.data.map((item: any) => {
      const isBlocked = item.reason && item.reason !== 'NotFilteredNotFound';
      return {
        domain: item.question?.name || item.domain || 'desconhecido',
        client: item.client || '--',
        time: item.time || new Date().toISOString(),
        elapsed_ms: item.elapsed_ms ? Number((item.elapsed_ms * 1000).toFixed(1)) : 0,
        status: isBlocked ? 'BLOCKED' : 'PROCESSED',
        reason: item.reason || 'OK',
        rule: item.rule || '',
        dns_type: item.question?.type || 'A'
      };
    });
    return lastCapturedQueryLog;
  }

  return [];
}


export async function getAdGuardFilteringStatus() {
  const result = await makeAdGuardRequest('/control/filtering/status');
  if (!result.ok) {
    throw new Error(result.error || 'Falha ao obter status de filtragem do AdGuard');
  }
  const data = result.data || {};
  return {
    enabled: data.enabled ?? true,
    interval: data.interval ?? 24,
    filters: Array.isArray(data.filters) ? data.filters : [],
    user_rules: Array.isArray(data.user_rules) ? data.user_rules : [],
    whitelist_filters: Array.isArray(data.whitelist_filters) ? data.whitelist_filters : []
  };
}

function normalizeAdGuardDomain(input: string): string {
  let d = String(input || '').trim().toLowerCase();
  if (!d) throw new Error('Domínio inválido');
  d = d.replace(/^https?:\/\//, '').replace(/\/.*$/, '').replace(/:\d+$/, '');
  d = d.replace(/^\*\./, '').replace(/^\.+|\.+$/g, '');
  if (!d || !/^[a-z0-9.-]+$/.test(d) || !d.includes('.')) {
    throw new Error('Domínio inválido. Use por exemplo: ads.exemplo.com');
  }
  return d;
}

function adGuardBlockRule(domain: string): string {
  return `||${domain}^$important`;
}

function adGuardAllowRule(domain: string): string {
  return `@@||${domain}^$important`;
}

export async function setAdGuardUserRules(rules: string[]) {
  const cleaned = (rules || []).map(r => String(r)).filter(r => r.trim() !== '');
  // remove duplicatas exatas preservando ordem
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const r of cleaned) {
    if (!seen.has(r)) { seen.add(r); unique.push(r); }
  }
  const result = await makeAdGuardRequest('/control/filtering/set_rules', 'POST', { rules: unique });
  if (!result.ok) {
    throw new Error(result.error || 'Falha ao salvar regras de usuário do AdGuard');
  }
  return { success: true, user_rules: unique };
}

export async function setAdGuardDomainBlocked(domainInput: string, blocked: boolean) {
  const domain = normalizeAdGuardDomain(domainInput);
  const status = await getAdGuardFilteringStatus();
  const current: string[] = Array.isArray(status.user_rules) ? status.user_rules.filter(Boolean) : [];
  const blockRule = adGuardBlockRule(domain);
  const allowRule = adGuardAllowRule(domain);

  // remove regras equivalentes existentes para o domínio (bloqueio/allow simples)
  const domainRe = domain.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const patterns = [
    new RegExp(`^\\|\\|${domainRe}\\^`, 'i'),
    new RegExp(`^@@\\|\\|${domainRe}\\^`, 'i'),
    new RegExp(`^${domainRe}$`, 'i'),
  ];
  let next = current.filter(r => !patterns.some(p => p.test(r.trim())));

  if (blocked) {
    next.push(blockRule);
  } else {
    next.push(allowRule);
  }

  await setAdGuardUserRules(next);
  const after = await getAdGuardFilteringStatus();
  return {
    success: true,
    domain,
    blocked,
    rule: blocked ? blockRule : allowRule,
    user_rules: Array.isArray(after.user_rules) ? after.user_rules : next,
    message: blocked
      ? `Domínio "${domain}" bloqueado com sucesso no AdGuard (user rules).`
      : `Domínio "${domain}" desbloqueado/permitido com sucesso no AdGuard (user rules).`
  };
}

export async function removeAdGuardDomainRule(domainInput: string) {
  const domain = normalizeAdGuardDomain(domainInput);
  const status = await getAdGuardFilteringStatus();
  const current: string[] = Array.isArray(status.user_rules) ? status.user_rules.filter(Boolean) : [];
  const domainRe = domain.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const patterns = [
    new RegExp(`^\\|\\|${domainRe}\\^`, 'i'),
    new RegExp(`^@@\\|\\|${domainRe}\\^`, 'i'),
    new RegExp(`^${domainRe}$`, 'i'),
  ];
  const next = current.filter(r => !patterns.some(p => p.test(r.trim())));
  await setAdGuardUserRules(next);
  const after = await getAdGuardFilteringStatus();
  return {
    success: true,
    domain,
    user_rules: Array.isArray(after.user_rules) ? after.user_rules : next,
    message: `Regras personalizadas para "${domain}" removidas.`
  };
}
